function setup() {
  createCanvas(600, 600);
  // noLoop() removed for animation
  noFill();
  strokeWeight(2.5);
}

function draw() {
  background("#cd1440");

  let n = 17;
  let s = width/n;

  let x = s, y = s;
  let i = 0;
  let _wG_1 = 0; while ((y < height-s*1.1) && ++_wG_1 < 20000) {
    let _wG_2 = 0; while ((x < width-s*1.1) && ++_wG_2 < 20000) {
      let tl = (random() < 1/2) ? s/2 : 0;
      let tr = (random() < 1/2) ? s/2 : 0;
      let br = (random() < 1/2) ? s/2 : 0;
      let bl = (random() < 1/2) ? s/2 : 0;
      stroke(0);
      square(x+2, y+2, s, tl, tr, br, bl);
      stroke("#fafafa");
      square(x, y, s, tl, tr, br, bl);
      x += 2*s;
    }
    x = s;
    y += s;
    if ((i++)%2 == 0) x += s;
  }
}
